out=g.copy()
blocks={9:[((0,2),(3,5)),((3,2),(9,11)),((6,2),(7,9)),((9,2),(12,14))],
        8:[((0,2),(12,14)),((12,2),(3,5)),((12,2),(9,11))],
        4:[((6,2),(12,14))]}
for c,bl in blocks.items():
    for (r0,dr),(c0,dc) in bl:
        for r in range(r0,r0+dr):
            for col in range(c0,c0+dc):
                if out[r,col]!=c: out[r,col]=c
# verify counts
for c in [4,8,9]: print(c,(out==c).sum())
print('\n'.join(' '.join(map(str,row)) for row in out))

h,w=g.shape
out2=[[0]*(w//3) for _ in range(h//3)]
for R in range(h//3):
    for C in range(w//3):
        t=g[3*R:3*R+3,3*C:3*C+3]
        cols={x for x in t.flatten() if x not in (0,5)}
        out2[R][C]=cols.pop() if len(cols)==1 else (list(cols)[0] if cols else 0)
print(out2)
